  async function loadAnalytics(panel){
    panel.innerHTML='<div class="account-panel"><p class="account-loading">Считаю сводку класса…</p></div>';
    try{
      const query=new URLSearchParams({inactivity_days:String(state.analyticsFilters.inactivity_days),missing_min:String(state.analyticsFilters.missing_min)});
      const data=await A.api(`/api/teacher/classes/${state.klass.id}/analytics?${query}`);
      const byCell=new Map(data.cells.map(cell=>[`${cell.student_id}:${cell.assignment_id}`,cell]));
      const statusShort={accepted:'✓',submitted:'↻',returned:'!',draft:'✎',not_started:'—'};
      const statusText={accepted:'Принято',submitted:'На проверке',returned:'Нужно доработать',draft:'Черновик',not_started:'Не начато'};
      const heatmap=data.assignments.length&&data.students.length?`<div class="account-table-wrap account-heatmap-wrap"><table class="account-table account-heatmap"><caption class="account-muted">Статусы заданий, оценка указана после принятия работы.</caption><thead><tr><th scope="col">Ученик</th>${data.assignments.map(item=>`<th scope="col" title="${esc(item.title)}">${esc(item.title)}</th>`).join('')}</tr></thead><tbody>${data.students.map(student=>`<tr><th scope="row">${esc(student.full_name)}</th>${data.assignments.map(assignment=>{const cell=byCell.get(`${student.id}:${assignment.id}`),status=cell?.status||'not_started',score=status==='accepted'&&cell.score!=null?` · ${cell.score}`:'',label=`${student.full_name} · ${assignment.title}: ${statusText[status]||status}${score}`;return `<td><span class="account-heat-cell" role="img" data-status="${status}" aria-label="${esc(label)}" title="${esc(label)}">${statusShort[status]||'—'}${status==='accepted'&&cell.score!=null?`<small>${cell.score}</small>`:''}</span>${cell?.id?`<button class="account-heat-open" type="button" data-open-submission="${cell.id}" aria-label="Открыть работу: ${esc(label)}">Открыть</button>`:''}</td>`;}).join('')}</tr>`).join('')}</tbody></table></div><p class="account-muted">Показаны первые ${data.students.length} учеников и ${data.assignments.length} опубликованных заданий. Статус обозначен и цветом, и символом; «Открыть» ведёт к отправленной работе.</p>`:'<div class="account-empty"><h3>Матрица пока пуста</h3><p>Добавь учеников и опубликуй задания, чтобы увидеть распределение работ.</p></div>';
      const risks=data.at_risk.length?`<ul class="account-risk-list">${data.at_risk.map(student=>`<li><button type="button" class="account-student-profile-link" data-student-action="profile" data-student="${student.id}">${esc(student.full_name)}</button><span>${Number(student.missing_count)?`${student.missing_count} не сдано`:''}${Number(student.missing_count)&&student.inactive?' · ':''}${student.inactive?`нет активности с ${student.last_activity_at?A.formatDate(student.last_activity_at):'начала курса'}`:''}</span></li>`).join('')}</ul>`:'<p class="account-muted">По выбранным порогам учеников нет.</p>';
      const errors=data.frequent_errors.length?`<div class="account-error-list">${data.frequent_errors.map(item=>`<article><div><strong>${esc(item.title)}</strong><p>${esc(item.check_label)} · не прошла ${item.failure_count} ${Number(item.failure_count)===1?'раз':'раза'} у ${item.students_count} ${studentCount(item.students_count)}</p></div><div class="account-actions">${(item.student_ids||[]).slice(0,6).map(id=>{const student=state.students.find(row=>Number(row.id)===Number(id));return student?`<button type="button" class="account-small-button" data-student-action="profile" data-student="${student.id}">${esc(student.full_name)}</button>`:'';}).join('')}</div></article>`).join('')}</div>`:'<p class="account-muted">Нет активных несданных работ с проваленными автопроверками.</p>';
      panel.innerHTML=`<div class="account-panel"><div class="account-panel-heading"><div><h3>Карта работ класса</h3><p class="account-muted">Сводка хранит до 40 учеников и 40 заданий на экран, чтобы таблица оставалась отзывчивой.</p></div><span class="account-count-pill">Запросы: ${data.timings_ms.total} мс</span></div><div class="account-heat-legend"><span><b>✓</b> Принято</span><span><b>↻</b> На проверке</span><span><b>!</b> На доработке</span><span><b>✎</b> Черновик</span><span><b>—</b> Не начато</span></div>${heatmap}</div><div class="account-analytics-grid"><section class="account-panel"><div class="account-panel-heading"><div><h3>Кому может понадобиться помощь</h3><p class="account-muted">Порог отсутствия и несданных работ настраивается.</p></div></div><form class="account-analytics-filters" data-analytics-filters><label>Нет активности, дней<input name="inactivity_days" type="number" min="1" max="90" value="${data.thresholds.inactivity_days}"></label><label>Не сдано заданий<input name="missing_min" type="number" min="1" max="20" value="${data.thresholds.missing_min}"></label><button class="account-small-button" type="submit">Обновить список</button></form>${risks}</section><section class="account-panel"><div class="account-panel-heading"><div><h3>Частые ошибки</h3><p class="account-muted">Группировка проваленных автопроверок по заданию и правилу.</p></div></div>${errors}</section></div>`;
    }catch(e){panel.innerHTML=`<div class="account-panel"><h3>Аналитика не загрузилась</h3><p class="account-message">${esc(e.message)}</p><button class="account-small-button" type="button" data-retry-analytics>Повторить</button></div>`;}
  }
